import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.CHeM0PsO.js";const E=JSON.parse('{"title":"安装与配置","description":"","frontmatter":{},"headers":[],"relativePath":"projects/tuneweave/docs/getting-started.md","filePath":"projects/tuneweave/docs/getting-started.md"}'),c={name:"projects/tuneweave/docs/getting-started.md"};function s(r,e,i,n,l,p){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="安装与配置" tabindex="-1">安装与配置 <a class="header-anchor" href="#安装与配置" aria-label="Permalink to &quot;安装与配置&quot;">​</a></h1><h2 id="运行预编译包" tabindex="-1">运行预编译包 <a class="header-anchor" href="#运行预编译包" aria-label="Permalink to &quot;运行预编译包&quot;">​</a></h2><p>从 GitHub Release 下载与系统匹配的单文件可执行程序：Windows 文件名为 <code>tuneweave-&lt;version&gt;-windows-&lt;architecture&gt;.exe</code>，Linux 和 macOS 文件名分别为 <code>tuneweave-&lt;version&gt;-linux-&lt;architecture&gt;</code> 和 <code>tuneweave-&lt;version&gt;-macos-&lt;architecture&gt;</code>，均无需解压。每个发布文件都有同名 <code>.sha256</code> 校验文件，下载程序也可以从仓库根目录的 <a href="../release-manifest.json"><code>release-manifest.json</code></a> 获取版本、文件名、下载地址和校验地址。</p><p>默认监听地址是 <code>127.0.0.1:7832</code>：</p><div class="language-console vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">curl http://127.0.0.1:7832/healthz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h2><p>需要 Rust 1.85 或更高版本：</p><div class="language-console vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cargo build --release --locked -p tuneweave-server --bin tuneweave</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>产物位于 <code>target/release/tuneweave</code>，Windows 位于 <code>target/release/tuneweave.exe</code>。</p><h2 id="基础配置" tabindex="-1">基础配置 <a class="header-anchor" href="#基础配置" aria-label="Permalink to &quot;基础配置&quot;">​</a></h2><p>TuneWeave 使用环境变量配置。未设置时可直接启动。</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>TUNEWEAVE_BIND</code></td><td><code>127.0.0.1:7832</code></td><td>HTTP 监听地址</td></tr><tr><td><code>TUNEWEAVE_DATA_DIR</code></td><td><code>data</code></td><td>账户、设备身份和 Uni Playlist 的私有数据目录</td></tr><tr><td><code>TUNEWEAVE_LOG_LEVEL</code></td><td><code>info</code></td><td><code>trace</code>、<code>debug</code>、<code>info</code>、<code>warn</code>、<code>error</code> 或 <code>off</code>；优先于 <code>RUST_LOG</code></td></tr><tr><td><code>TUNEWEAVE_LOG_FORMAT</code></td><td><code>human</code></td><td><code>human</code> 或 <code>json</code></td></tr><tr><td><code>TUNEWEAVE_LOG_DIR</code></td><td><code>logs</code></td><td>日志目录</td></tr><tr><td><code>TUNEWEAVE_LOG_FILE</code></td><td><code>tuneweave.log</code></td><td>日志文件名前缀</td></tr><tr><td><code>TUNEWEAVE_LOG_TO_STDERR</code></td><td><code>true</code></td><td>是否输出到标准错误</td></tr><tr><td><code>TUNEWEAVE_LOG_TO_FILE</code></td><td><code>true</code></td><td>是否输出到文件</td></tr><tr><td><code>TUNEWEAVE_LOG_RETENTION_DAYS</code></td><td><code>14</code></td><td>日志保留天数</td></tr><tr><td><code>TUNEWEAVE_LOG_MAX_FILES</code></td><td><code>30</code></td><td>最大日志文件数</td></tr><tr><td><code>TUNEWEAVE_LOG_MAX_FILE_BYTES</code></td><td><code>16777216</code></td><td>单个日志文件上限</td></tr><tr><td><code>TUNEWEAVE_LOG_MAX_TOTAL_BYTES</code></td><td><code>268435456</code></td><td>日志总空间上限</td></tr></tbody></table><p>默认 <code>human</code> 格式使用本机日期和时间，以 <code>[组件][等级][时间] 消息</code> 输出；交互式控制台会为组件、等级和时间添加颜色，写入日志文件时不会包含 ANSI 转义序列。需要机器处理时可设置 <code>TUNEWEAVE_LOG_FORMAT=json</code>，保留结构化字段并关闭颜色。</p><p>平台代理只能由部署方配置，调用方不能在 API 请求中覆盖：</p><table tabindex="0"><thead><tr><th>平台</th><th>代理变量</th></tr></thead><tbody><tr><td>网易云音乐</td><td><code>TUNEWEAVE_NETEASE_PROXY</code></td></tr><tr><td>QQ 音乐</td><td><code>TUNEWEAVE_QQ_PROXY</code></td></tr><tr><td>B 站</td><td><code>TUNEWEAVE_BILIBILI_PROXY</code></td></tr><tr><td>酷狗音乐</td><td><code>TUNEWEAVE_KUGOU_PROXY</code></td></tr><tr><td>咪咕音乐</td><td><code>TUNEWEAVE_MIGU_PROXY</code></td></tr><tr><td>酷我音乐</td><td><code>TUNEWEAVE_KUWO_PROXY</code></td></tr><tr><td>汽水音乐</td><td><code>TUNEWEAVE_SODA_PROXY</code></td></tr></tbody></table><p>网易云音乐还支持以下部署配置：</p><ul><li><code>TUNEWEAVE_NETEASE_COOKIE</code>：为 <code>default</code> 账户提供启动 Cookie。</li><li><code>TUNEWEAVE_NETEASE_REAL_IP</code>：为 provider 固定一个 IPv4 请求身份。</li><li><code>TUNEWEAVE_NETEASE_RANDOM_CN_IP=true</code>：启动时生成并复用一个中国 IPv4 请求身份，不能与固定地址同时使用。</li></ul><h2 id="数据与安全" tabindex="-1">数据与安全 <a class="header-anchor" href="#数据与安全" aria-label="Permalink to &quot;数据与安全&quot;">​</a></h2><p>默认情况下，运行目录中的 <code>data</code> 保存服务器托管账户凭证、平台设备身份和 Server 模式 Uni Playlist，<code>logs</code> 保存运行日志。生产环境应将它们放在仅服务账户可读写的本地目录中，不要放入公开目录、同步盘或镜像；也可以分别通过 <code>TUNEWEAVE_DATA_DIR</code> 和 <code>TUNEWEAVE_LOG_DIR</code> 指定其他位置。</p><p>TuneWeave 不在静态数据文件中保存登录密码或短信验证码，但账户会话仍属于敏感信息。对外提供服务时应在可信反向代理后启用 HTTPS，并禁止代理记录 <code>X-TuneWeave-Credential</code>、Cookie、请求体和媒体签名 URL。</p><h2 id="运行检查" tabindex="-1">运行检查 <a class="header-anchor" href="#运行检查" aria-label="Permalink to &quot;运行检查&quot;">​</a></h2><div class="language-console vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">curl http://127.0.0.1:7832/v1/platforms</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">curl http://127.0.0.1:7832/v1/capabilities</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">curl &quot;http://127.0.0.1:7832/v1/search?q=海阔天空&amp;type=track&amp;platform=all&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>平台支持的能力可能受地区、账户权益和上游服务状态影响。调用方应先读取 <code>/v1/capabilities</code>，并按 <a href="./api-v1.html">HTTP API v1</a> 处理统一错误。</p>`,23)])])}const u=t(c,[["render",s]]);export{E as __pageData,u as default};
